def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    count = 2
    total = v1 + v2
    value = total / count
    return {
        "value": value,
        "trace": {
            "values": [v1, v2],
            "total": total,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
